import sys

data = sys.stdin.read().split()
n = int(data[0])
k = int(data[1])
a = data[2:2 + n]
where = {}
for i in range(n):
    where.setdefault(a[i], []).append(i + 1)
fresh = len(where)
groans = 0
for positions in where.values():
    for x in range(1, len(positions)):
        if positions[x] - positions[x - 1] > k:
            groans += 1
print(fresh, groans)
